package jsondiff

// diffStats holds diagnostic counters collected during a
// comparison. The counters are meant for observability and
// testing purposes only; they have no effect on the patch
// generated by a Differ. Each Differ instance owns its own
// counters, thus concurrent comparisons performed by distinct
// instances are isolated from each other.
type diffStats struct {
	// comparisons is the number of deep-equality comparisons
	// performed while matching the elements of arrays (LCS)
	// and while discovering move/copy candidates.
	comparisons int
}

func (s *diffStats) reset() {
	s.comparisons = 0
}

// Equality relation memoization states.
const (
	eqUnknown uint8 = iota
	eqFalse
	eqTrue
)

// arrayMatcher unifies the responsibilities of equality
// testing, hashing and longest-common-subsequence computation
// for a single pair of arrays.
//
// The digest of each element is computed exactly once, and
// the equality relation between a pair of source and target
// indices is evaluated with deepEqual at most once: digests
// act as a pre-filter, and the outcome of each deep-equality
// comparison is memoized so that the dynamic programming
// phase and the backtracking phase of the LCS computation
// share the same candidates instead of recomputing them.
//
// Note that digests are only ever used as a negative filter;
// a digest match is always confirmed with a deep-equality
// comparison, which guarantees that distinct values that
// happen to share the same digest (hash collision) are never
// incorrectly paired together.
type arrayMatcher struct {
	src     []interface{}
	tgt     []interface{}
	srcHash []uint64
	tgtHash []uint64
	memo    []uint8
	stats   *diffStats
}

// newArrayMatcher returns an arrayMatcher for the given
// source and target slices. The digests of the elements of
// both slices are computed upfront, exactly once per element,
// using the given hasher. The comparison outcomes are recorded
// in the given stats, if non-nil.
func newArrayMatcher(src, tgt []interface{}, h *hasher, stats *diffStats) *arrayMatcher {
	m := &arrayMatcher{
		src:     src,
		tgt:     tgt,
		srcHash: make([]uint64, len(src)),
		tgtHash: make([]uint64, len(tgt)),
		memo:    make([]uint8, len(src)*len(tgt)),
		stats:   stats,
	}
	for i, v := range src {
		m.srcHash[i] = h.digest(v, false)
	}
	for i, v := range tgt {
		m.tgtHash[i] = h.digest(v, false)
	}
	return m
}

// equal reports whether the elements at index i of the source
// and index j of the target are deeply equal. The result of
// the deep-equality comparison is computed at most once per
// pair of indices; subsequent calls return the memoized state.
func (m *arrayMatcher) equal(i, j int) bool {
	if m.srcHash[i] != m.tgtHash[j] {
		// The digests differ, the values cannot be equal.
		// This is a cheap pre-filter that does not require
		// a deep-equality comparison.
		return false
	}
	k := i*len(m.tgt) + j
	switch m.memo[k] {
	case eqTrue:
		return true
	case eqFalse:
		return false
	}
	// The digests match, confirm with a deep-equality
	// comparison and memoize the outcome. This is the
	// only place where a comparison is accounted for.
	if m.stats != nil {
		m.stats.comparisons++
	}
	if deepEqual(m.src[i], m.tgt[j]) {
		m.memo[k] = eqTrue
		return true
	}
	m.memo[k] = eqFalse
	return false
}

// pairs computes the longest common subsequence of the source
// and target slices and returns the index pairs of the LCS,
// that is, the indices into the source and target slices
// where the LCS items are located.
func (m *arrayMatcher) pairs() [][2]int {
	t := make([][]int, len(m.src)+1)

	for i := 0; i <= len(m.src); i++ {
		t[i] = make([]int, len(m.tgt)+1)
	}
	for i := 1; i < len(t); i++ {
		for j := 1; j < len(t[i]); j++ {
			if m.equal(i-1, j-1) {
				t[i][j] = t[i-1][j-1] + 1
			} else {
				t[i][j] = max(t[i-1][j], t[i][j-1])
			}
		}
	}
	i, j := len(m.src), len(m.tgt)
	s := make([][2]int, 0, t[i][j])

	for i > 0 && j > 0 {
		switch {
		case m.equal(i-1, j-1):
			s = append(s, [2]int{i - 1, j - 1})
			i--
			j--
		case t[i-1][j] > t[i][j-1]:
			i--
		default:
			j--
		}
	}
	for i, j := 0, len(s)-1; i < j; i, j = i+1, j-1 {
		s[i], s[j] = s[j], s[i]
	}
	return s
}
